/**
 * עצים כאימפוסטורים (החלטת הקונסיל 18.9.2026): ריאליזם של עץ בא מתעבורת אור בין אלפי עלים — את זה מרנדרים OFFLINE.
 * עץ סרוק אמיתי (Poly Haven island_tree_02, CC0, ~1M פוליגונים) נאפה ב-Blender Cycles ל-16 מבטים סביב העץ, מואר בהעתק של
 * ריג הדמדומים של האתר (scripts/blender/impostor_bake.py → impostor_pack.py → public/stage/trees/tree_a[_m].webp).
 * כאן: מרובע לכל עץ, שלט-חוצות צילינדרי שפונה למצלמה, בוחר את שני המבטים הקרובים לפי זווית המצלמה ומערבב ביניהם.
 * התאורה אפויה וקבועה בעולם → אין סיבוב yaw למופעים. צל: פרוקסי בלתי נראה (colorWrite=false) שמטיל למפת הצל הקיימת.
 */
import * as THREE from 'three';

export interface TreeSlot { x: number; y: number; z: number; h: number; near: 0 | 1 | 2; }

const VIEWS = 16, COLS = 4, ROWS = 4;
const ASPECT = 448 / 320;        // רוחב/גובה פריים
const TREE_IN_FRAME = 0.7685;    // גובה העץ מתוך גובה הפריים (tree_a.json: treeH / frameH)
const GROUND_V = 0.105;          // קו הקרקע בתוך הפריים (כויל ויזואלית)

export async function loadTrees(base: string, slots: TreeSlot[], scene: THREE.Scene, low: boolean, S: number, done: () => void) {
  if (!slots.length) return;
  const tex = await new THREE.TextureLoader().loadAsync(`${base}trees/tree_a${low ? '_m' : ''}.webp`);
  tex.colorSpace = THREE.SRGBColorSpace; tex.anisotropy = low ? 2 : 8; tex.generateMipmaps = true;
  tex.minFilter = THREE.LinearMipmapLinearFilter; tex.wrapS = tex.wrapT = THREE.ClampToEdgeWrapping;

  const fog = scene.fog as THREE.FogExp2 | null;
  const mat = new THREE.ShaderMaterial({
    uniforms: {
      map: { value: tex }, uS: { value: S }, uGain: { value: 1.3 },
      fogColor: { value: fog ? fog.color : new THREE.Color(0) }, fogDensity: { value: fog ? fog.density : 0 },
    },
    // דסקטופ: alpha-to-coverage על MSAA (קצה חלק, כותב עומק). מובייל (בלי MSAA אמין, פיקסלים מתוחים ×2–3): ערבוב אלפא אמיתי ורך —
    // חיתוך קשיח שם נראה כמו "יהלומים מנצנצים" סביב הצללית בזמן גלילה
    side: THREE.DoubleSide, transparent: low, alphaToCoverage: !low, depthWrite: !low, premultipliedAlpha: false,
    vertexShader: /* glsl */`
      attribute vec2 aVar; // x = היסט מבט (בפריימים), y = מתיחת רוחב — כדי ששכנים לא יהיו תאומים
      uniform float uS; varying vec2 vUvA; varying vec2 vUvB; varying float vBlend; varying float vFogDepth;
      const float N = ${VIEWS}.0; const float COLS = ${COLS}.0; const float ROWS = ${ROWS}.0;
      vec2 cell(float i, vec2 uv) { float c = mod(i, COLS); float r = floor(i / COLS); return vec2((c + uv.x) / COLS, 1.0 - (r + 1.0 - uv.y) / ROWS); }
      void main() {
        vec3 ip = (modelMatrix * instanceMatrix * vec4(0., 0., 0., 1.)).xyz;
        float sc = length((instanceMatrix * vec4(0., 1., 0., 0.)).xyz);
        vec3 toCam = cameraPosition - ip;
        vec3 right = normalize(vec3(toCam.z, 0., -toCam.x));
        vec3 wp = ip + right * position.x * sc * aVar.y * ${ASPECT.toFixed(4)} + vec3(0., 1., 0.) * (position.y - ${GROUND_V.toFixed(3)}) * sc;
        float a = atan(toCam.x * uS, toCam.z);                       // LTR: הסצנה משתקפת → הזווית משתקפת
        float f = mod(a / 6.2831853 * N + aVar.x + N, N);
        float i0 = floor(f), i1 = mod(i0 + 1., N);
        vBlend = smoothstep(0.3, 0.7, f - i0);                       // כמעט snap — גזע כפול נראה רק בחלון צר
        vec2 uv = vec2(uS < 0. ? 0.5 - position.x : position.x + 0.5, position.y);
        // שוליים של חצי טקסל בתוך כל פריים — בלי דליפה מהפריים השכן ב-mip
        uv = clamp(uv, vec2(0.004), vec2(0.996));
        vUvA = cell(i0, uv); vUvB = cell(i1, uv);
        vec4 mv = viewMatrix * vec4(wp, 1.); vFogDepth = -mv.z;
        gl_Position = projectionMatrix * mv;
      }`,
    fragmentShader: /* glsl */`
      uniform sampler2D map; uniform float uGain; uniform vec3 fogColor; uniform float fogDensity;
      varying vec2 vUvA; varying vec2 vUvB; varying float vBlend; varying float vFogDepth;
      void main() {
        vec4 ca = texture2D(map, vUvA), cb = texture2D(map, vUvB);
        vec4 c = mix(ca, cb, vBlend);
        ${low
          ? 'float al = smoothstep(0.08, 0.75, c.a); if (al < 0.01) discard;      // מובייל: קצה רך, מעורבב'
          : 'float al = clamp((c.a - 0.5) / max(fwidth(c.a), 1e-4) + 0.5, 0., 1.); if (al < 0.02) discard;   // דסקטופ: קצה של פיקסל אחד, MSAA מחליק'}
        // האטלס הוא straight-alpha עם RGB מורחב מתחת לשקוף — אסור לחלק באלפא (זה הבהיר כל פיקסל-קצה עד פי 3 = נצנוץ סביב הצללית)
        vec3 col = c.rgb * uGain;
        gl_FragColor = vec4(col, al);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
        float ff = 1.0 - exp(-fogDensity * fogDensity * vFogDepth * vFogDepth);
        gl_FragColor.rgb = mix(gl_FragColor.rgb, pow(fogColor, vec3(1. / 2.2)) * 0.9, ff * 0.0);
      }`,
  });
  // ערפל: צבע הערפל עובר את אותו tone-mapping רק בחומרים רגילים; כאן מערבבים לפני ה-tonemapping
  mat.fragmentShader = mat.fragmentShader
    .replace('vec3 col = c.rgb * uGain;', 'vec3 col = c.rgb * uGain;\n        col = mix(col, fogColor, 1.0 - exp(-fogDensity * fogDensity * vFogDepth * vFogDepth));')
    .replace(/float ff =[\s\S]*?ff \* 0\.0\);/, '');

  if (low) slots = [...slots].sort((a, b) => a.z - b.z || a.x * S - b.x * S); // ערבוב אלפא: רחוקים קודם (רוב המצלמות מביטות ל-‎-z / ‎-x)
  const quad = new THREE.PlaneGeometry(1, 1).translate(0, 0.5, 0);
  // וריאציה דטרמיניסטית: היסט של עד ±2 מבטים (±45°) — הצללית משתנה מאוד, כיוון האור האפוי עדיין אמין; רוחב ±8%
  const vars = new Float32Array(slots.length * 2);
  slots.forEach((t, i) => { const h = Math.sin(t.x * 12.9898 + t.z * 78.233) * 43758.5453; const r = h - Math.floor(h); vars[i * 2] = Math.round(r * 4) - 2; vars[i * 2 + 1] = 0.92 + ((r * 7.3) % 1) * 0.16; });
  quad.setAttribute('aVar', new THREE.InstancedBufferAttribute(vars, 2));
  const mesh = new THREE.InstancedMesh(quad, mat, slots.length);
  const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), p = new THREE.Vector3(), s = new THREE.Vector3();
  slots.forEach((t, i) => mesh.setMatrixAt(i, m4.compose(p.set(t.x, t.y, t.z), q, s.setScalar(t.h / TREE_IN_FRAME))));
  mesh.frustumCulled = false; mesh.castShadow = false; mesh.receiveShadow = false;
  scene.add(mesh);

  // פרוקסי צל: כתר (איקוסהדרון מעוך) + גזע, בלתי נראים למצלמה אבל מטילים צל ארוך ונכון למפת הצל של אור המפתח
  const ghost = new THREE.MeshBasicMaterial({ colorWrite: false, depthWrite: false });
  const crown = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1, 1), ghost, slots.length);
  const trunk = new THREE.InstancedMesh(new THREE.CylinderGeometry(1, 1, 1, 5), ghost, slots.length);
  slots.forEach((t, i) => {
    crown.setMatrixAt(i, m4.compose(p.set(t.x, t.y + t.h * 0.68, t.z), q, s.set(t.h * 0.55, t.h * 0.3, t.h * 0.55)));
    trunk.setMatrixAt(i, m4.compose(p.set(t.x, t.y + t.h * 0.22, t.z), q, s.set(t.h * 0.035, t.h * 0.44, t.h * 0.035)));
  });
  for (const g of [crown, trunk]) { g.castShadow = true; g.frustumCulled = false; g.renderOrder = -1; scene.add(g); }
  done();
}
